def swap_adjacent_chars(s):
    chars = list(s)
    for i, char in enumerate(chars):
        if i % 2 == 0:
            if i + 1 < len(chars):
                chars[i:i+2] = [chars[i+1], chars[i]]
    return ''.join(chars)

